    /**
     * Dle moznosti prohlizece otestuje, zda je dana metoda podporovana. Pokud vrati false, lze posledni chybu nacist pomoci metody 'getLastMessage()'
     * @param {any} args String nebo pole stringu. V pripade pole u prvni metody, ktera neni podporovana, skonci testovani.
     * @returns {boolean} True, je-li metoda podporovana prohlizecem.
     */
    isSupported(args) {
        var otherArgs = this.prepareInputArguments(args);
        for (var i = 0; i < otherArgs.length; i++) {
            var method = this.browserExtrasApp[otherArgs[i]];
            if (!method)
                throw new GError("Method '" + args[i] + "' does not exists.");
            if (!method.call(this.browserExtrasApp, GBrowserExtrasClass.isTest))
                return false;
        }
        return true;
    }
    checkMethod(args, softCheck = true) {
        var otherArgs = this.prepareInputArguments(args);
        let def = $.Deferred();
        let checkPromises = {};
        let proms = [];
        for (var i = 0; i < otherArgs.length; i++) {
            var method = this.browserExtrasApp[otherArgs[i]];
            if (!method)
                throw new GError("Method '" + otherArgs[i] + "' does not exists.");
            checkPromises[otherArgs[i]] = (method.call(this.browserExtrasApp, softCheck ? GBrowserExtrasClass.softCheck : GBrowserExtrasClass.hardCheck));
            proms.push(checkPromises[otherArgs[i]]);
        }
        $.when.apply($, $.map(proms, function (i) {
            var dfd = $.Deferred();
            // you can add .done and .fail if you want to keep track of each results individualy
            i.always(function () { dfd.resolve(); });
            return dfd.promise();
        })).always(() => {
            let names = Object.getOwnPropertyNames(checkPromises);
            let results = {};
            for (let i = 0; i < names.length; i++) {
                results[names[i]] = checkPromises[names[i]].state() === "resolved";
            }
            def.resolve(results);
        });
        return def.promise();
    }
    isSupportedPromise(args) {
        try {
            return this.browserExtrasApp.waitForSupportedPromise().then((isSupported) => {
                return isSupported ? this.isSupported(args) : $.Deferred().resolve(false).promise();
            });
        }
        catch (ex) {
            this.logger.warn("isSupportedPromise: " + ex.message);
            return $.Deferred().reject(ex).promise();
        }
    }
    getSupportedState(args) {
        var supportState = {};
        var operations = this.prepareInputArguments(args);
        var that = this;
        var firstProm = $.Deferred();
        var nextProm = firstProm.promise(); // ? otestovat
        for (var i = 0; i < operations.length; i++) {
            (function (index) {
                nextProm = nextProm.then(function () {
                    var method = that.browserExtrasApp[operations[index]];
                    return (method !== null) ? method.call(that.browserExtrasApp, GBrowserExtrasClass.getState) : {};
                }).then(function (stateResult) {
                    supportState[operations[index]] = stateResult;
                    return $.Deferred().resolve().promise();
                });
            })(i);
        }
        firstProm.resolve();
        return nextProm.then(function () { return supportState; });
    }
    testCommunication(requiredOperation = null) {
        try {
            return this.browserExtrasApp["testCommunication"](requiredOperation);
        }
        catch (ex) {
            this.logger.warn("getExtensionState: " + ex.message);
            return $.Deferred().reject({
                handled: false, operation: null, reason: ex.message, type: EReasonType.common
            }).promise();
        }
    }
