    getOpenDocumentTimeout() {
        try {
            let browser = this.browserExtrasApp.getBrowserType();
            if (browser === EBrowserTypes.IE) {
                return 10000;
            }
            else {
                return 100;
            }
        }
        catch (ex) {
            this.logger.warn("getOpenDocumentTimeout: " + ex.message);
            this._lastMessage = ex.message;
            return 10000;
        }
    }
