                    let handlePromise = evHandlerResult.handlePromise ?? $.Deferred().reject($.extend({ reason: "BrowserExtras.canOpenFile: Operation is not supported", handled: false }, reason)).promise();
                    handlePromise.then((result) => { def.resolve(result); }, (r) => { def.reject(r); });
