    documentPluginUpload(url, content, headers) {
        if (arguments[0] === GBrowserExtrasClass.isTest || arguments[0] === GBrowserExtrasClass.softCheck || arguments[0] === GBrowserExtrasClass.hardCheck || arguments[0] === GBrowserExtrasClass.getState) {
            return this.processArgument("documentPluginUpload", arguments[0]);
        }
        var def = $.Deferred();
        if (this.activeXPluginUploadSupported()) {
            const fsSrv = new GContent("Gordic.Gui.WebControls.GDocumentService");
            fsSrv.call("SetUpSecurityKey")
                .then(() => {
                var xhr = this.activeXPluginUploadCreate();
                xhr.open("POST", url);
                $.each(headers, function (k, v) {
                    xhr.setRequestHeader(k, v);
                });
                xhr.onreadystatechange = function () {
                    if (xhr.readyState === 4) {
                        if (xhr.status === 200)
                            def.resolve(xhr);
                        else
                            def.reject(xhr);
                    }
                };
                xhr.send(content);
            }, () => { def.reject(); })
                .always(() => { fsSrv.close(); });
        }
        else if (this.browserExtensionIsSupported()) {
            var fd = content;
            if (fd && fd instanceof FormData && fd.forEach) {
                //NOTE (BM 2021-01-21): Upload po castech. Rozdil je ve vystupu, kde GDocument.js s nim pocita. Na misto 
                //                      standardniho se vraci GFileInfoDto[]! Syncovat vzdy s GDocument.js!!!
                let fileInfos = new Array();
                let dd = $.Deferred().resolve(fileInfos).promise();
                fd.forEach((val, key) => {
                    if (val instanceof Blob)
                        dd = dd.then((fiArr) => {
                            return Gordic.Utils.File.chunkUpload(val, key, undefined)
                                .then((fi) => { fiArr.push(fi); return fiArr; });
                        });
                });
                dd.then((fiArr) => { def.resolve(fiArr); }); //Vraci se GFileInfoDto[]!
                return dd.promise();
            }
            $.ajax({
                url: url,
                type: 'POST',
                data: content, //NOTE: FormData je podporovan az od IE 10, na IE 9 zrejme bude muset byt pouzit ActiveX
                processData: false,
                contentType: false,
                headers: headers
            }).then((result) => { def.resolve(result); }, (reason) => { def.reject({ reason: reason.responseText, handled: false, operation: OperationsEnum.file, type: EReasonType.serverError }); });
        }
        else {
            let rejectObject = this.getRejectObject("documentPluginUpload", OperationsEnum.file);
            let evHandlerResult = this.triggerSupportEvent({ type: "run", operation: "documentPluginUpload", needUpdate: rejectObject.type === EReasonType.extensionNotSupported });
            let handlePromise = evHandlerResult.handlePromise ?? $.Deferred().reject(rejectObject).promise();
            handlePromise.then((result) => { def.resolve(result); }, (r) => { def.reject(r); });
        }
        return def.promise();
    }
