        this.logger.trace("getAllCerts - spusteni" + new Date().toJSON());
        var def = $.Deferred();
        if (this.activeXCryptoSupported()) {
            try {
                this.logger.trace("getAllCerts - ActiveX section");
                // *** Sekce RTOMES ***
                var l_oPdfAX = this.activeXCryptoCreate();
                // var result = l_oPdfAX.CertificateList(); // ax23, ale uz nekompatibilni s novym vyberem certifikatu
                var result = l_oPdfAX.GetAllCertificates(); // ax24
                def.resolve(JSON.parse(JSON.parse(result).Response).responseData);
                this.logger.trace("getAllCerts - resolve promise");
            }
            catch (ex) {
                this.logger.warn("getAllCerts: Access to certificates has been failed. Reason: " + ex.message);
                def.reject({ reason: "GBrowserExtras.getAllCerts: Access to certificates has been failed.", handled: false, type: EReasonType.common, operation: OperationsEnum.cert });
            }
            // *** End sekce RTOMES ***
        }
