            class GSignpostSearchResolver extends Gordic.Components.Search.GTaskSearchResolver {
                constructor(opts) {
                    super(null);
                    this.options = opts;
                }
                getDefaultDomain() {
                    return {
                        id: this.options.domainName,
                        name: "Úloha", //RC 31750046 : Úloha 
                        description: "Vyhledat a spustit úlohu podle názvu nebo popisu úlohy" //RC 31750045 : Vyhledat a spustit úlohu podle názvu nebo popisu úlohy
                    };
                }
                getTaskList() {
                    const tasklistParams = [];
                    var linearizeActions = this.linearizeParams(this.options.actions);
                    for (let i = 0, ii = linearizeActions?.length ?? 0; i < ii; i++) {
                        const mainAct = linearizeActions[i];
                        if (!mainAct.visible || !mainAct.caption)
                            continue;
                        if (tasklistParams.find((mp) => mp.action === mainAct.action))
                            tasklistParams.push(mainAct);
                    }
                    return tasklistParams;
                }
                createDefaultAction() {
                    return new GAction({
                        caption: "Spustit úlohu", //RC 31750047 : Spustit úlohu
                        name: "taskexec",
                        run: (ev, ctx) => { $.content('main').navigateTask([this.options.mainContent, { runAction: ctx.item.data }]); /* (ctx.item.data.action as GAction)?.run(ev, ctx.item.data.actionContext ? $.extend(ctx, ctx.item.data.actionContext) : ctx);*/ },
                    });
                }
            }
