                        const pdfEventBus = new window.pdfjsViewer.EventBus({ dispatchToDOM: true });
                        const pdfLinkService = new window.pdfjsViewer.PDFLinkService({ eventBus: pdfEventBus });
                        const pdfFindController = new window.pdfjsViewer.PDFFindController({ eventBus: pdfEventBus, linkService: pdfLinkService });
