var Gordic;
(function (Gordic) {
    var Utils;
    (function (Utils) {
        /**
         * Třída s pomocnými statickými metodami pro metodickou nápovědu
         */
        class GContextHelpController {
            /**
             * Statická funkce sloužící pro konverzi blogové dto z db na dto metodické nápovědy
             * @param articles Gordic.Gin.Interface.GContextHelpBlogDto
             */
            static convertBlogsToCtxHelp(articles) {
                var enumPriority = function (enumPriority) {
                    switch (enumPriority) {
                        case 0: { // 0-32
                            return 0;
                        }
                        case 10: { // 33-65
                            return 33;
                        }
                        case 20: { // 66-99
                            return 66;
                        }
                        case 30: { // 100-INF
                            return 100;
                        }
                        default: {
                            return 0;
                        }
                    }
                };
                return articles.map(function (item) {
                    let help = {
                        id: item.ixs_clb,
                        constraints: [],
                        title: item.nazev,
                        chapter: item.blog_txt,
                        contentType: Gordic.Widget.GContextHelpContentType.md,
                        priority: enumPriority(item.priorita_clb),
                        modified: item.dat_zmena,
                        author: item.zmenu_prov_txt,
                        keywords: [],
                        confirmed: item.potvrzeno_uzivatelem,
                        load: function () {
                            return (Gordic.Isl.BlogClanek.read({
                                data: {
                                    ixs_clb: item.ixs_clb,
                                    withRecord: true
                                },
                                fragments: ["Udalosti"]
                            }).getData().done((data) => {
                                const decoded = decodeURIComponent(window.atob(data.obsah ?? ""));
                                this.content = decoded;
                                this.load = undefined;
                            }));
                        },
                        confirm: function () {
                            return Gordic.Isl.BlogClanekUdalost.create({
                                data: {
                                    ixs_clb: this.id,
                                    zmena_clb: 20,
                                    aktivita: 100,
                                    poznamka: 'jres:25000137', //RC 25000137 : Potvrzeno uživatelem
                                }
                            }).getData().done((ol) => {
                                this.confirmed = new Date();
                                this.confirm = undefined;
                            });
                        }
                    };
                    if ((help.priority && help.priority < 100) || help.confirmed != undefined) {
                        help.confirm = undefined;
                    }
                    for (var tag of item.tagy?.trim().split(/\s*;\s*/g) ?? [])
                        if (tag.startsWith("chapter:"))
                            help.chapter = tag.substring(8);
                        else if (tag.indexOf(":") > 0)
                            help.constraints?.push(tag);
                        else
                            help.keywords?.push(tag);
                    return help;
                });
            }
            /**
             * Statická funkce složící pro převod a vyplnění DTO metodické nápovědy z ResourcePackage
             * @param helps JSON z ResourcePackage
             * @param userSettings UserSetting
             */
            static convertPckgToCtxHelp(helps, userSettings) {
                const rxMDLinks = /\[(.+)\]\(([A-Za-z0-9:/._~-]+)(?: \"(.+)\")?\)/g; // [AltText](url "title") - zjednodusena verze, neumi dobre ()[] uvnitr jinych zavorek. Spravny regexp potrebuje look-behind, ktery IE11 neumi (a spadne na script syntax error)
                var fileIdMap = {}; // mapa na file.md => ID, protoze pokud ID md clanku neodpovida automaticke ceste (custom id), je nutne linky primo na soubory nahradit ID clanku (pokud neni id vyplneno, je tvoreno nazvem md filu a linky funguji spravne)
                return helps.map(function (help) {
                    help = $.extend({}, help);
                    help.id = help.id || (help.file || help.title || "").replace(/[\s()"']+/g, "_") || null;
                    help.priority = (help.priority) ? parseInt(help.priority) || 0 : 0;
                    if (help.priority >= 100 && help.id && userSettings && userSettings.getDef("read", []).indexOf(help.id) < 0) {
                        help.confirm = function () {
                            var promise = $.Deferred();
                            this.confirm = undefined;
                            userSettings.set("read", userSettings.getDef("read", []).concat(this.id));
                            userSettings.save(true);
                            return promise.resolve();
                        };
                    }
                    else {
                        help.confirm = undefined;
                    }
                    if (help.file) {
                        if (help.file.endsWith(".pdf")) {
                            help.content = Gordic.Utils.gz("help", help.file);
                            help.contentType = Gordic.Widget.GContextHelpContentType.pdf;
                        }
                        else if (help.file.endsWith(".md")) {
                            fileIdMap[help.file] = help.id;
                            help.contentType = Gordic.Widget.GContextHelpContentType.md;
                            help.load = function () {
                                var files = help.file.split(/\s*[,;]\s*/g);
                                var rels = files.map(file => file.substr(0, file.lastIndexOf('/') + 1)); // vysbirame relativni cesty pro vnitrni odkazy
                                return $.when.apply(null, files.map(file => $.get(Gordic.Utils.gz("help", file)).then(res => res))) // identifikujeme vice souboru => premapujeme na requesty => z (response, status, jqXHR) udelame (response), jinak je typ vysledku $.when zavisly na poctu souboru
                                    .done((...mds) => {
                                    this.load = undefined;
                                    this.content = mds
                                        .map((md, idx) => md.replace(rxMDLinks, (match, text, url, title) => url.indexOf(":") < 0 ? "[{0}]({1}{2})".format(text, url.endsWith(".md") || url.indexOf(".md#") > 0 ? "help:" + (fileIdMap[rels[idx] + url] || (rels[idx] + url)) : Gordic.Utils.gz("help", rels[idx] + url), title ? ' "' + title + '"' : '') : match))
                                        .join("\n");
                                });
                            };
                        }
                        else
                            console.log("Help: unknown article type '{0}' id:'{1}'".format(help.files, help.id));
                    }
                    if (typeof help.keywords === "string")
                        help.keywords = help.keywords.split(/\s*[,;]\s*/g);
                    if (typeof help.constraints === "string")
                        help.constraints = help.constraints.split(/\s*;\s*/g);
                    return help;
                });
            }
            /**
             * Statická funkce pro aplikování constraint na zadané články
             * @param articles Vstupní články pro vyfiltrování
             * @param constraints Vstupní constraint na aplikování na články
             * @returns Vyfiltrované články
             */
            static applyConstraints(toc, articles, constraints) {
                if (articles == null || articles == undefined) {
                    return toc;
                }
                var cmd = constraints[0] ?? "";
                if (cmd.startsWith("id:")) { // rychle hledani dle id
                    var artID = cmd.substring(3);
                    toc.articles.push(...articles.filter(art => art.id === artID)); // pri hledani podle id nerespektujeme article.chapter
                    return toc;
                }
                for (let art of articles)
                    if (cmd === "show:all" || // zobrazeni vsech
                        !Array.isArray(art.constraints) || art.constraints.length === 0 || // clanky bez omezeni
                        art.constraints.some(ac => ac.split("&").every(cpart => constraints.indexOf(cpart.trim()) >= 0)) // clanky vyhovujici kontextovemu constraintu
                    )
                        toc.chapter(art.chapter || "general").articles.push(art);
                return toc;
            }
        }
        Utils.GContextHelpController = GContextHelpController;
    })(Utils = Gordic.Utils || (Gordic.Utils = {}));
})(Gordic || (Gordic = {}));
