                        throw new GError(33100019, `33100060`); //RC-EX 33100060 : Chybí povinný name ${JSON.stringify(lib)}
                    const menuBarPole = new Array();
                    let form = new Gordic.Forms.Form({
                        layoutDescriptor: "L1M1S1, L-0-6-6, M-0-6-6, S-0-6-6",
                        name: "Formular",
                    })
                        .addSection()
                        .addText(lib.licenseText);
