                        model: "model.{0} = value.{1}".format("Referent_IxsRef" /* GDetailZastupuDlgDtoNames.Referent_IxsRef */, "ixs_ref" /* Gordic.Data.Readers.GinsrefDtoNames.ixs_ref */),
                        //name: "Referent",
