var Gordic;
(function (Gordic) {
    var Gui;
    (function (Gui) {
        var WebApp;
        (function (WebApp) {
            /**
             * GZmenaFunkceHandler
             *
             * @author  TFeik
             * @date    27.08.2021
             * @since   486.1.0.118
             */
            class GZmenaFunkceHandler {
                /**
                 * Vyvolá změnu funkce.
                 *
                 * @author  TFeik
                 * @date    27.08.2021
                 *
                 * @param {{ content?: GContent }} [input]
                 * @returns {JQuery.Promise<any>}
                 */
                static ZmenitFunkci(input) {
                    return GDlg.confirm('jres:32142502', //RC 32142502 : Změna funkce
                    'jres:32142503' //RC 32142503 : Změna funkce způsobí ukončení aktuální práce. Opravdu chcete změnit funkci?
                    )
                        .createDialogPromise()
                        .then((answer) => {
                        if (answer !== 'yes') {
                            return $.Deferred().reject().promise();
                        }
                        // 07.08.20025 - TFeik
                        // Odhlášení a otevření přihlašovací obrazovky přesunuto do samostatné metody ReopenApp.
                        return GZmenaFunkceHandler.ReopenApp(input?.content, {
                            // 16.09.2025 - TRuzicka
                            // po změně se přepne do režimu 3, aby došlo k zobrazení vlastních funkčních místi a zároveň i zástupů
                            Rezim: 3
                        }, {
                            ticketType: Gordic.Enums.TicketType.WithLogin
                        });
                    });
                }
                /**
                 * Vyvolá změnu zastupovaného veřejného uživatele.
                 *
                 * @author  TFeik
                 * @date    08.09.2021
                 *
                 * @returns {JQuery.Promise<any>}
                 */
                static ZmenitPublicUzivatele() {
                    $.content('main').changeUserContext({
                        change: 'publicUser'
                    });
                    return $.Deferred().resolve().promise();
                }
                /**
                 * Otevře dialog pro přidání zastupované osoby veřejného uživatele.
                 *
                 * @author  TFeik
                 * @date    08.09.2021
                 *
                 * @returns {JQuery.Promise<WebControls.GAddRepresentPublicUserDlgReturnValue | undefined>}
                 */
                static PridatPublicZastupUzivatele() {
                    return Gordic.Gui.Dialogs.GAddRepresentPublicUserDlg({
                        parentContent: $.content('main'),
                        opt: {}
                    });
                }
                /**
                 * Odhlásí uživatele z aplikace a znovu otevře přihlašovací stránku aplikace s
                 * potlačením přeskakování kroku pro zadání uživatele.
                 *
                 * @author  truzicka
                 * @date    16.09.2025
                 */
                static ReopenAppWithoutSkipUserSelectionStep() {
                    try {
                        const mainContent = $.content("main");
                        const mojeFaze = mainContent?.applicationRevision.slice(0, 7) ?? "41Unknown05";
                        const loginWidgetName = "gordic-glogin";
                        const storageName = loginWidgetName + mojeFaze;
                        const contract = GData.GLocalStorage.getContract(storageName, {});
                        if (contract) {
                            const stored = contract.value ?? {};
                            const keys = Object.keys(stored).filter(k => k.startsWith("GWebSequence"));
                            keys.forEach(k => {
                                const value = stored[k];
                                if (typeof value !== "object" || value === null)
                                    stored[k] = { skipUserSelectionStep: false };
                                else
                                    value.skipUserSelectionStep = false;
                            });
                            contract.value = stored;
                        }
                        else {
                            console.warn("ReopenAppWithoutSkipUserSelectionStep: contract nenalezen:", storageName);
                        }
                    }
                    catch (e) {
                        console.warn("ReopenAppWithoutSkipUserSelectionStep: chyba při nastavování skipUserSelectionStep=false", e);
                    }
                    return GZmenaFunkceHandler.ReopenApp(undefined, {
                        // nulování proměnných z ULR, které způsobují problémy se změnou výchozího profilu
                        // pokud je hodnota null, je tento parametr odstraněn z URL
                        Profile: null,
                        User: null,
                        Ticket: null
                    }, {
                        ticketType: Gordic.Enums.TicketType.None
                    });
                }
                /**
                 * Ohlásí uživatele z aplikace a znovu otevře přihlašovací stránku aplikace.
                 *
                 * @author  TFeik
                 * @date    07.08.2025
                 *
                 * @param {GContent} [content] (Default: $.content('main')) Content ma kterém se zavolá odhlášení.
                 * @param {ObjectLiteral<any>} [data] Object to searialize into query.
                 * @param {Gordic.WebApp.Utility.IGLinkOptions} [options]  ticketType(Gordic.Enums.TicketType) - default is .None
                 * @returns {JQuery.Promise<string>}
                 */
                static ReopenApp(content, data, options) {
                    return Gordic.WebApp.Utility.createCommandUrl(null, null, data, options)
                        .then((url) => {
                        const deferred = $.Deferred();
                        $(document).on('applicationclosed', () => {
                            if (window.location.href == url)
                                window.location.reload();
                            else
                                window.location.href = url;
                            deferred.resolve();
                        });
                        const lognoutContent = content ?? $.content('main');
                        lognoutContent.logout();
                        return deferred.promise();
                    });
                }
            }
            WebApp.GZmenaFunkceHandler = GZmenaFunkceHandler;
        })(WebApp = Gui.WebApp || (Gui.WebApp = {}));
    })(Gui = Gordic.Gui || (Gordic.Gui = {}));
})(Gordic || (Gordic = {}));
